let __pysecCatalog = PYSEC_CATALOG_EMBED || "";
let __pysecReady = false;
let __pysecInitPromise = null;
let __pyodide = null;
let __pysecPkgFiles = null; // { path: Uint8Array }

/**
 * Catalog injection (perf): memoize body; full list once per conversation.
 */
/** @type {string|null} */
let __pysecCatalogPromptCached = null;

/** @returns {Promise<string>} */
async function loadPysecCatalog() {
  if (__pysecCatalog && __pysecCatalog.length) return __pysecCatalog;
  __pysecCatalog = (typeof PYSEC_CATALOG_EMBED === "string" && PYSEC_CATALOG_EMBED) ? PYSEC_CATALOG_EMBED : "";
  return __pysecCatalog;
}

/** Static full catalog body (built once). */
function pysecCatalogBody() {
  if (__pysecCatalogPromptCached) return __pysecCatalogPromptCached;
  const text = (typeof PYSEC_CATALOG_EMBED === "string" && PYSEC_CATALOG_EMBED)
    ? PYSEC_CATALOG_EMBED
    : (__pysecCatalog || "");
  __pysecCatalog = text;
  const n = (typeof PYSEC_TOOL_COUNT === "number" ? PYSEC_TOOL_COUNT : 0) || (text.match(/^\s{2}\S/gm) || []).length;
  __pysecCatalogPromptCached =
    "### CATALOG n=" + n + "  tool_id(params!) !=required\n" +
    text + (text.endsWith("\n") ? "" : "\n");
  return __pysecCatalogPromptCached;
}

/**
 * @param {{full?: boolean}} [opts] full=false skips catalog body (already in system history)
 * @returns {string}
 */
function pysecCatalogBlurb(opts) {
  // Category mode: never dump 141 tools into the prompt
  void opts;
  const kit = __pysecReady ? "ready" : "embedded";
  const n = (typeof PYSEC_TOOL_COUNT === "number" ? PYSEC_TOOL_COUNT : 141);
  if (typeof categoryKitBlurb === "function") {
    return "\n" + categoryKitBlurb();
  }
  return "\nUnsure → kit discover. Never list tools.\n";
}

/** @returns {object[]} */
function pysecCatalogTools() {
  // Do not cache empty — catalog JSON may load later in the same file
  if (Array.isArray(pysecCatalogTools._c) && pysecCatalogTools._c.length) {
    return pysecCatalogTools._c;
  }
  try {
    const raw = typeof PYSEC_CATALOG_JSON === "string" ? PYSEC_CATALOG_JSON : "[]";
    const arr = JSON.parse(raw);
    pysecCatalogTools._c = Array.isArray(arr) ? arr : [];
  } catch (_) {
    pysecCatalogTools._c = pysecCatalogTools._c || [];
  }
  return pysecCatalogTools._c;
}



/** Minimal ustar reader for embedded package */
function untarU8(u8) {
  const files = [];
  let offset = 0;
  const td = new TextDecoder("ascii");
  function str(start, len) {
    let s = td.decode(u8.subarray(offset + start, offset + start + len));
    const z = s.indexOf("\0");
    return (z >= 0 ? s.slice(0, z) : s).trim();
  }
  while (offset + 512 <= u8.length) {
    // empty block ends archive
    let zero = true;
    for (let i = 0; i < 512; i++) {
      if (u8[offset + i] !== 0) { zero = false; break; }
    }
    if (zero) break;
    const name = str(0, 100);
    const sizeStr = str(124, 12);
    const size = parseInt(sizeStr, 8) || 0;
    const typeFlag = u8[offset + 156];
    const prefix = str(345, 155);
    let full = prefix ? prefix.replace(/\/?$/, "/") + name : name;
    full = full.replace(/^\.\//, "");
    offset += 512;
    const data = u8.subarray(offset, offset + size);
    offset += Math.ceil(size / 512) * 512;
    // regular file: type 0 or '0' (48)
    if (name && (typeFlag === 0 || typeFlag === 48 || typeFlag === undefined)) {
      files.push({ path: full, data: new Uint8Array(data) });
    }
  }
  return files;
}

async function inflatePysecPackage() {
  if (__pysecPkgFiles) return __pysecPkgFiles;
  const t0 = performance.now();
  const u8 = typeof b64ToU8 === "function" ? b64ToU8(PYSEC_PKG_GZ_B64) : (() => {
    const bin = atob(PYSEC_PKG_GZ_B64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  })();
  let raw;
  if (typeof inflateMaybe === "function") raw = inflateMaybe(u8);
  else if (window.pako && window.pako.ungzip) raw = window.pako.ungzip(u8);
  else throw new Error("pako missing — cannot unzip embedded pysec package");
  const files = untarU8(raw);
  const map = Object.create(null);
  for (const f of files) {
    if (f.path && f.path.endsWith(".py")) map[f.path] = f.data;
  }
  const ms = performance.now() - t0;
  console.log("[goar] inflate pysec-pkg", (u8.length / 1048576).toFixed(2), "→", (raw.length / 1048576).toFixed(2), "MB",
    files.length, "files", ms.toFixed(0) + "ms");
  __pysecPkgFiles = map;
  return map;
}

